// Raw-HTML stash, mirroring Python-Markdown's util.HtmlStash behavior.
// Raw HTML blocks are stored away during parsing and replaced by
// placeholders; the placeholders are substituted back at the end.

export const BLOCK_PLACEHOLDER_PREFIX = 'wzxhzdk:';
export const INLINE_PLACEHOLDER_PREFIX = 'klzzwxh:';

export class HtmlStash {
  constructor(prefix = BLOCK_PLACEHOLDER_PREFIX) {
    this.prefix = prefix;
    this.entries = [];
  }

  store(html) {
    const index = this.entries.length;
    this.entries.push(html);
    return this.placeholder(index);
  }

  placeholder(index) {
    return `${this.prefix}${index}`;
  }

  get(index) {
    return this.entries[index];
  }

  // Replace every placeholder occurrence in `text` with the stored html.
  restore(text) {
    return text.replace(
      new RegExp(`${this.prefix}(\\d+)`, 'g'),
      (m, i) => this.entries[Number(i)]
    );
  }
}

