// Minimal re-implementation of Pygments' HtmlFormatter (nowrap mode),
// as used by Python-Markdown's codehilite extension.
//
// Token = [cssClass, value]. Empty cssClass means plain text (Token.Text).

// Pygments' _escape_html_table
const ESCAPE_TABLE = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

export function escapePygments(text) {
  return text.replace(/[&<>"']/g, (ch) => ESCAPE_TABLE[ch]);
}

// Mirror of HtmlFormatter._format_lines: token values are split at
// newlines so that <span> elements never cross line boundaries.
export function formatTokens(tokens) {
  let out = '';
  for (const [cls, value] of tokens) {
    const escaped = escapePygments(value);
    const parts = escaped.split('\n');
    for (let i = 0; i < parts.length; i++) {
      if (i > 0) out += '\n';
      const part = parts[i];
      if (part === '') continue;
      out += cls ? `<span class="${cls}">${part}</span>` : part;
    }
  }
  return out;
}

// Mirror of pygments.highlight(): ensures the source ends with a newline.
export function highlight(code, tokenize) {
  let text = code;
  if (!text.endsWith('\n')) text += '\n';
  return formatTokens(tokenize(text));
}

// Pygments TextLexer equivalent: the whole input is a single Text token.
export function tokenize(code) {
  if (code === '') return [];
  return [['', code]];
}

// Simplified re-implementation of Pygments' PythonLexer, calibrated
// against the observed token classes of the bundled Pygments version.

const KEYWORDS = new Set([
  'assert', 'async', 'await', 'break', 'continue', 'del', 'elif', 'else',
  'except', 'finally', 'for', 'global', 'if', 'lambda', 'nonlocal', 'pass',
  'raise', 'return', 'try', 'while', 'with', 'yield',
]);

const CONSTANTS = new Set(['None', 'True', 'False', 'NotImplemented']);
const PSEUDO = new Set(['self', 'cls']);

const BUILTINS = new Set([
  '__import__', 'abs', 'all', 'any', 'ascii', 'bin', 'bool', 'breakpoint',
  'bytearray', 'bytes', 'callable', 'chr', 'classmethod', 'compile',
  'complex', 'delattr', 'dict', 'dir', 'divmod', 'enumerate', 'eval',
  'exec', 'filter', 'float', 'format', 'frozenset', 'getattr', 'globals',
  'hasattr', 'hash', 'help', 'hex', 'id', 'input', 'int', 'isinstance',
  'issubclass', 'iter', 'len', 'list', 'locals', 'map', 'max', 'memoryview',
  'min', 'next', 'object', 'oct', 'open', 'ord', 'pow', 'print', 'property',
  'range', 'repr', 'reversed', 'round', 'set', 'setattr', 'slice', 'sorted',
  'staticmethod', 'str', 'sum', 'super', 'tuple', 'type', 'vars', 'zip',
]);

const EXCEPTIONS = new Set([
  'ArithmeticError', 'AssertionError', 'AttributeError', 'BaseException',
  'BlockingIOError', 'BrokenPipeError', 'BufferError', 'ChildProcessError',
  'ConnectionAbortedError', 'ConnectionError', 'ConnectionRefusedError',
  'ConnectionResetError', 'EOFError', 'EnvironmentError', 'Exception',
  'FileExistsError', 'FileNotFoundError', 'FloatingPointError', 'IOError',
  'ImportError', 'IndentationError', 'IndexError', 'InterruptedError',
  'IsADirectoryError', 'KeyError', 'KeyboardInterrupt', 'LookupError',
  'MemoryError', 'ModuleNotFoundError', 'NameError', 'NotADirectoryError',
  'NotImplementedError', 'OSError', 'OverflowError', 'PermissionError',
  'ProcessLookupError', 'RecursionError', 'ReferenceError', 'RuntimeError',
  'StopAsyncIteration', 'StopIteration', 'SyntaxError', 'SystemError',
  'SystemExit', 'TabError', 'TimeoutError', 'TypeError', 'UnboundLocalError',
  'UnicodeDecodeError', 'UnicodeEncodeError', 'UnicodeError',
  'UnicodeTranslateError', 'ValueError', 'ZeroDivisionError',
]);

const MAGIC_FUNCS = new Set([
  '__init__', '__new__', '__call__', '__del__', '__repr__', '__str__',
  '__bytes__', '__format__', '__lt__', '__le__', '__eq__', '__ne__', '__gt__',
  '__ge__', '__hash__', '__bool__', '__getattr__', '__getattribute__',
  '__setattr__', '__delattr__', '__dir__', '__get__', '__set__', '__delete__',
  '__set_name__', '__len__', '__length_hint__', '__getitem__', '__setitem__',
  '__delitem__', '__missing__', '__iter__', '__reversed__', '__contains__',
  '__add__', '__sub__', '__mul__', '__matmul__', '__truediv__', '__floordiv__',
  '__mod__', '__divmod__', '__pow__', '__lshift__', '__rshift__', '__and__',
  '__xor__', '__or__', '__radd__', '__rsub__', '__rmul__', '__rmatmul__',
  '__rtruediv__', '__rfloordiv__', '__rmod__', '__rdivmod__', '__rpow__',
  '__rlshift__', '__rrshift__', '__rand__', '__rxor__', '__ror__', '__iadd__',
  '__isub__', '__imul__', '__imatmul__', '__itruediv__', '__ifloordiv__',
  '__imod__', '__ipow__', '__ilshift__', '__irshift__', '__iand__', '__ixor__',
  '__ior__', '__neg__', '__pos__', '__abs__', '__invert__', '__complex__',
  '__int__', '__float__', '__index__', '__round__', '__trunc__', '__floor__',
  '__ceil__', '__enter__', '__exit__', '__aenter__', '__aexit__', '__aiter__',
  '__anext__', '__await__', '__copy__', '__deepcopy__', '__reduce__',
  '__reduce_ex__', '__getstate__', '__setstate__', '__sizeof__', '__init_subclass__',
]);

const MAGIC_VARS = new Set([
  '__name__', '__doc__', '__package__', '__loader__', '__spec__', '__file__',
  '__cached__', '__builtins__', '__module__', '__class__', '__dict__',
  '__slots__', '__qualname__', '__annotations__', '__debug__', '__all__',
  '__version__', '__author__', '__path__', '__bases__', '__mro__',
  '__subclasses__', '__docformat__',
]);

// Split a string body into string tokens, pulling out escape sequences
// as String.Escape (se), like Pygments does for Python strings.
function splitEscapes(body, cls) {
  const tokens = [];
  let buf = '';
  for (let i = 0; i < body.length; i++) {
    if (body[i] === '\\' && i + 1 < body.length) {
      if (buf) { tokens.push([cls, buf]); buf = ''; }
      tokens.push(['se', body.slice(i, i + 2)]);
      i++;
    } else {
      buf += body[i];
    }
  }
  if (buf) tokens.push([cls, buf]);
  return tokens;
}

// Parse an f-string body (after the opening quote). Returns {tokens, end}.
function parseFString(code, start, quote, strCls) {
  const tokens = [];
  let i = start;
  let buf = '';
  const flush = () => { if (buf) { tokens.push(...splitEscapes(buf, strCls)); buf = ''; } };
  while (i < code.length) {
    const ch = code[i];
    if (code.startsWith(quote, i)) {
      flush();
      tokens.push([strCls, quote]);
      return { tokens, end: i + quote.length };
    }
    if (ch === '\\' && i + 1 < code.length) {
      buf += code.slice(i, i + 2);
      i += 2;
      continue;
    }
    if (ch === '{') {
      if (code[i + 1] === '{') { buf += '{{'; i += 2; continue; }
      flush();
      tokens.push(['si', '{']);
      i++;
      // expression up to the matching '}' at nesting depth 0
      let depth = 0;
      let exprStart = i;
      while (i < code.length) {
        const c = code[i];
        if (c === '{' || c === '(' || c === '[') depth++;
        else if (c === '}' && depth === 0) break;
        else if (c === '}' || c === ')' || c === ']') depth--;
        i++;
      }
      const expr = code.slice(exprStart, i);
      if (expr) tokens.push(...tokenize(expr));
      if (code[i] === '}') {
        tokens.push(['si', '}']);
        i++;
      }
      continue;
    }
    if (ch === '}') {
      if (code[i + 1] === '}') { buf += '}}'; i += 2; continue; }
      buf += ch;
      i++;
      continue;
    }
    if (ch === '\n' && quote.length === 1) {
      // unterminated single-line f-string
      flush();
      return { tokens, end: i };
    }
    buf += ch;
    i++;
  }
  flush();
  return { tokens, end: i };
}

// Parse a plain (non-f) string starting at `start` (the quote itself).
function parseString(code, start, quote, strCls) {
  const tokens = [];
  let i = start + quote.length;
  let buf = quote;
  while (i < code.length) {
    if (code.startsWith(quote, i)) {
      buf += quote;
      i += quote.length;
      tokens.push(...splitEscapes(buf, strCls));
      return { tokens, end: i };
    }
    const ch = code[i];
    if (ch === '\\' && i + 1 < code.length) {
      buf += code.slice(i, i + 2);
      i += 2;
      continue;
    }
    if (ch === '\n' && quote.length === 1) {
      break; // unterminated
    }
    buf += ch;
    i++;
  }
  tokens.push(...splitEscapes(buf, strCls));
  return { tokens, end: i };
}

const NAME_RE = /^[A-Za-z_][A-Za-z0-9_]*/;
const NUMBER_RES = [
  [/^0[xX][0-9a-fA-F_]+/, 'mh'],
  [/^0[oO][0-7_]+/, 'mo'],
  [/^0[bB][01_]+/, 'mb'],
  [/^0[0-7_]+/, 'mo'],
  [/^(\d[\d_]*\.\d[\d_]*([eE][+-]?\d+)?|\.\d+([eE][+-]?\d+)?|\d[\d_]*[eE][+-]?\d+)/, 'mf'],
  [/^\d[\d_]*/, 'mi'],
];
const OPERATOR_RE = /^(\*\*=|\/\/=|>>=|<<=|:=|==|!=|<=|>=|\*\*|\/\/|->|\.\.\.|[-~+/*%=<>&^|.@]=?)/;
const PUNCT_RE = /^[[\]{}:(),;]/;

export function tokenize(code) {
  const tokens = [];
  let i = 0;
  let expect = null; // 'nf' | 'nc' | null
  while (i < code.length) {
    const rest = code.slice(i);
    let m;

    if (rest[0] === '\n') { tokens.push(['', '\n']); i++; continue; }

    if ((m = rest.match(/^#[^\n]*/))) { tokens.push(['c1', m[0]]); i += m[0].length; continue; }

    if ((m = rest.match(/^@[A-Za-z_][A-Za-z0-9_.]*/))) { tokens.push(['nd', m[0]]); i += m[0].length; continue; }

    // strings with optional prefix
    if ((m = rest.match(/^([rRbBuUfF]{1,2})("""|'''|"|')/)) || (m = rest.match(/^()("""|'''|"|')/))) {
      const [, prefix, quote] = m;
      if (prefix) tokens.push(['sa', prefix]);
      const isF = /[fF]/.test(prefix);
      const strCls = quote.length === 3 ? 'sd' : (quote === '"' ? 's2' : 's1');
      let parsed;
      if (isF) {
        tokens.push([strCls, quote]);
        parsed = parseFString(code, i + prefix.length + quote.length, quote, strCls);
      } else {
        parsed = parseString(code, i + prefix.length, quote, strCls);
      }
      tokens.push(...parsed.tokens);
      i = parsed.end;
      expect = null;
      continue;
    }

    if ((m = rest.match(/^(def|class)([ \t]+)/))) {
      tokens.push(['k', m[1]]);
      tokens.push(['w', m[2]]);
      expect = m[1] === 'def' ? 'nf' : 'nc';
      i += m[0].length;
      continue;
    }

    if ((m = rest.match(/^(import|from)([ \t]+)/))) {
      tokens.push(['kn', m[1]]);
      tokens.push(['w', m[2]]);
      i += m[0].length;
      continue;
    }

    if ((m = rest.match(/^(import|from|as)\b/))) {
      tokens.push(['kn', m[0]]); i += m[0].length; continue;
    }

    if ((m = rest.match(NAME_RE))) {
      const word = m[0];
      if (expect) {
        tokens.push([expect, word]);
        expect = null;
      } else if (KEYWORDS.has(word)) tokens.push(['k', word]);
      else if (CONSTANTS.has(word)) tokens.push(['kc', word]);
      else if (PSEUDO.has(word)) tokens.push(['bp', word]);
      else if (/^__.*__$/.test(word)) {
        tokens.push([MAGIC_FUNCS.has(word) ? 'fm' : (MAGIC_VARS.has(word) ? 'vm' : 'vm'), word]);
      } else if (BUILTINS.has(word)) tokens.push(['nb', word]);
      else if (EXCEPTIONS.has(word)) tokens.push(['ne', word]);
      else if (word === 'in' || word === 'is' || word === 'and' || word === 'or' || word === 'not') tokens.push(['ow', word]);
      else tokens.push(['n', word]);
      i += word.length;
      continue;
    }

    let matched = false;
    for (const [re, cls] of NUMBER_RES) {
      if ((m = rest.match(re))) { tokens.push([cls, m[0]]); i += m[0].length; matched = true; break; }
    }
    if (matched) continue;

    if ((m = rest.match(OPERATOR_RE))) { tokens.push(['o', m[0]]); i += m[0].length; continue; }

    if ((m = rest.match(PUNCT_RE))) { tokens.push(['p', m[0]]); i += m[0].length; continue; }

    if ((m = rest.match(/^[ \t]+/))) { tokens.push(['', m[0]]); i += m[0].length; continue; }

    // fallback: single char as plain text
    tokens.push(['', rest[0]]);
    i++;
  }
  return tokens;
}

