// Simplified re-implementation of Pygments' JavascriptLexer, calibrated
// against the observed token classes of the bundled Pygments version.

const KEYWORDS = new Set([
  'for', 'while', 'do', 'break', 'return', 'continue', 'switch', 'case',
  'default', 'if', 'else', 'throw', 'try', 'catch', 'finally', 'yield',
  'this', 'super', 'extends', 'class', 'async', 'await', 'static', 'get',
  'set', 'of', 'in', 'debugger', 'with', 'export', 'import', 'from',
]);

const DECLARATIONS = new Set(['var', 'let', 'const', 'function']);

const WORD_OPERATORS = new Set([
  'new', 'delete', 'typeof', 'instanceof', 'void', 'in', 'of',
]);

const CONSTANTS = new Set([
  'true', 'false', 'null', 'undefined', 'NaN', 'Infinity',
]);

const BUILTINS = new Set([
  'Array', 'ArrayBuffer', 'BigInt', 'Boolean', 'DataView', 'Date',
  'decodeURI', 'decodeURIComponent', 'encodeURI', 'encodeURIComponent',
  'Error', 'EvalError', 'eval', 'Float32Array', 'Float64Array', 'Function',
  'Generator', 'GeneratorFunction', 'globalThis', 'Int8Array', 'Int16Array',
  'Int32Array', 'isFinite', 'isNaN', 'JSON', 'Map', 'Math', 'Number',
  'Object', 'parseFloat', 'parseInt', 'Promise', 'Proxy', 'RangeError',
  'ReferenceError', 'Reflect', 'RegExp', 'Set', 'SharedArrayBuffer',
  'String', 'Symbol', 'SyntaxError', 'TypeError', 'Uint8Array',
  'Uint8ClampedArray', 'Uint16Array', 'Uint32Array', 'unescape', 'URIError',
  'WeakMap', 'WeakSet', 'escape', 'require', 'module', 'exports', 'process',
  'window', 'document', 'navigator', 'alert', 'fetch', 'setTimeout',
  'setInterval', 'clearTimeout', 'clearInterval',
]);

const OPERATOR_RE = /^(\*\*=|===|!==|>>>|<<=|>>=|\.\.\.|=>|==|!=|<=|>=|\+\+|--|&&|\|\||\+=|-=|\*=|\/=|%=|&=|\|=|\^=|<<|>>|\*\*|\?\?|\?\.|[-+*/%<>=!~&|^?:])/;

function parseTemplate(code, start) {
  // start points at the opening backtick
  const tokens = [['sb', '`']];
  let i = start + 1;
  let buf = '';
  const flush = () => { if (buf) { tokens.push(['sb', buf]); buf = ''; } };
  while (i < code.length) {
    const ch = code[i];
    if (ch === '\\' && i + 1 < code.length) { buf += code.slice(i, i + 2); i += 2; continue; }
    if (ch === '`') { flush(); tokens.push(['sb', '`']); return { tokens, end: i + 1 }; }
    if (ch === '$' && code[i + 1] === '{') {
      flush();
      tokens.push(['si', '${']);
      i += 2;
      let depth = 1;
      const exprStart = i;
      while (i < code.length && depth > 0) {
        if (code[i] === '{') depth++;
        else if (code[i] === '}') depth--;
        if (depth > 0) i++;
      }
      const expr = code.slice(exprStart, i);
      if (expr) tokens.push(...tokenize(expr));
      if (code[i] === '}') { tokens.push(['si', '}']); i++; }
      continue;
    }
    buf += ch;
    i++;
  }
  flush();
  return { tokens, end: i };
}

export function tokenize(code) {
  const tokens = [];
  let i = 0;
  // whether a regex literal may appear at the current position
  let regexAllowed = true;
  let m;

  while (i < code.length) {
    const rest = code.slice(i);

    if ((m = rest.match(/^\s+/))) {
      tokens.push(['w', m[0]]);
      i += m[0].length;
      continue;
    }
    if ((m = rest.match(/^\/\/[^\n]*/))) {
      tokens.push(['c1', m[0]]); i += m[0].length; regexAllowed = true; continue;
    }
    if ((m = rest.match(/^\/\*[\s\S]*?\*\//))) {
      tokens.push(['cm', m[0]]); i += m[0].length; regexAllowed = true; continue;
    }
    if (rest[0] === '`') {
      const parsed = parseTemplate(code, i);
      tokens.push(...parsed.tokens);
      i = parsed.end;
      regexAllowed = false;
      continue;
    }
    if ((m = rest.match(/^"(\\[\s\S]|[^"\\\n])*("|$)/)) || (m = rest.match(/^'(\\[\s\S]|[^'\\\n])*('|$)/))) {
      // trim a trailing newline from the "$" end case
      let val = m[0];
      if (val.endsWith('\n')) val = val.slice(0, -1);
      tokens.push([rest[0] === '"' ? 's2' : 's1', val]);
      i += val.length;
      regexAllowed = false;
      continue;
    }
    if (regexAllowed && (m = rest.match(/^\/(\\[\s\S]|[^\/\\\n])+\/[a-z]*/))) {
      tokens.push(['sr', m[0]]); i += m[0].length; regexAllowed = false; continue;
    }
    if ((m = rest.match(/^0[xX][0-9a-fA-F_]+/))) {
      tokens.push(['mh', m[0]]); i += m[0].length; regexAllowed = false; continue;
    }
    if ((m = rest.match(/^0[bB][01_]+/))) {
      tokens.push(['mb', m[0]]); i += m[0].length; regexAllowed = false; continue;
    }
    if ((m = rest.match(/^0[oO][0-7_]+/))) {
      tokens.push(['mo', m[0]]); i += m[0].length; regexAllowed = false; continue;
    }
    if ((m = rest.match(/^(\d[\d_]*\.[\d_]*|\.\d+|\d[\d_]*)([eE][+-]?\d+)?n?/))) {
      tokens.push(['mf', m[0]]); i += m[0].length; regexAllowed = false; continue;
    }
    if ((m = rest.match(/^[A-Za-z_$][A-Za-z0-9_$]*/))) {
      const word = m[0];
      if (DECLARATIONS.has(word)) tokens.push(['kd', word]);
      else if (WORD_OPERATORS.has(word)) tokens.push(['ow', word]);
      else if (CONSTANTS.has(word)) tokens.push(['kc', word]);
      else if (BUILTINS.has(word)) tokens.push(['nb', word]);
      else if (KEYWORDS.has(word)) tokens.push(['k', word]);
      else tokens.push(['nx', word]);
      i += word.length;
      regexAllowed = word === 'return' || word === 'case' || word === 'throw' ||
        word === 'typeof' || word === 'delete' || word === 'void' ||
        word === 'in' || word === 'of' || word === 'new' ||
        word === 'instanceof' || word === 'else' || word === 'do' || word === 'yield';
      continue;
    }
    if ((m = rest.match(OPERATOR_RE))) {
      tokens.push(['o', m[0]]); i += m[0].length; regexAllowed = true; continue;
    }
    if ((m = rest.match(/^[[\]{}();,.]/))) {
      const ch = m[0];
      tokens.push(['p', ch]); i++;
      regexAllowed = ch !== ')' && ch !== ']' && ch !== '}';
      continue;
    }
    tokens.push(['', rest[0]]);
    i++;
    regexAllowed = false;
  }
  return tokens;
}

// Simplified re-implementation of Pygments' BashLexer, calibrated
// against the observed token classes of the bundled Pygments version.

const KEYWORDS = new Set([
  'if', 'then', 'else', 'elif', 'fi', 'for', 'while', 'until', 'do', 'done',
  'case', 'esac', 'function', 'select', 'in', 'break', 'continue', 'return',
  'time', 'coproc',
]);

const BUILTINS = new Set([
  'alias', 'bg', 'bind', 'builtin', 'caller', 'cd', 'command', 'compgen',
  'complete', 'compopt', 'declare', 'dirs', 'disown', 'echo', 'enable',
  'eval', 'exec', 'exit', 'export', 'fc', 'fg', 'getopts', 'hash', 'help',
  'history', 'jobs', 'kill', 'let', 'local', 'logout', 'mapfile', 'popd',
  'printf', 'pushd', 'pwd', 'read', 'readonly', 'set', 'shift', 'shopt',
  'source', 'suspend', 'test', 'times', 'trap', 'type', 'typeset', 'ulimit',
  'umask', 'unalias', 'unset', 'wait', 'readarray',
]);

// tokens that may precede a comment start
const PRE_COMMENT = new Set([';', '&&', '||', '|', '(', '{', ';;', '&']);

export function tokenize(code) {
  return tokenizeInner(code, 0, code.length, { substDepth: 0 }).tokens;
}

function tokenizeInner(code, start, end, state) {
