  let prev = null; // previous significant token value
  let m;

  const lastWasNewline = () => {
    for (let k = tokens.length - 1; k >= 0; k--) {
      const v = tokens[k][1];
      if (v === '' ) continue;
      return v.endsWith('\n');
    }
    return true; // start of input
  };

  while (i < end) {
    const rest = code.slice(i, end);

    if ((m = rest.match(/^\s+/))) {
      tokens.push(['w', m[0]]); i += m[0].length;
      continue;
    }

    if (rest[0] === '#' && (prev === null || lastWasNewline() || PRE_COMMENT.has(prev))) {
      m = rest.match(/^#[^\n]*/);
      tokens.push(['c1', m[0]]); i += m[0].length; prev = m[0];
      continue;
    }

