    if (rest[0] === ')' && (prev === null || true)) { tokens.push(['o', ')']); i++; prev = ')'; continue; }
    if ((m = rest.match(/^[;|&]/))) {
      tokens.push(['p', m[0]]); i++; prev = m[0]; continue;
    }

