// Simplified re-implementation of Pygments' HtmlLexer, calibrated
// against the observed token classes of the bundled Pygments version.

import { tokenize as tokenizeJs } from './javascript.mjs';

function tokenizeTag(code, i) {
  // assumes code[i] === '<' and it is a tag (opening or closing)
  const tokens = [];
  let m;
  const rest = code.slice(i);
  if ((m = rest.match(/^<\/[A-Za-z][^>]*>/))) {
    // closing tag: split into </ , name, >
    tokens.push(['p', '</']);
    const inner = m[0].slice(2, -1);
    const nameMatch = inner.match(/^[A-Za-z][A-Za-z0-9:-]*/);
    tokens.push(['nt', nameMatch[0]]);
    const tail = inner.slice(nameMatch[0].length);
    if (tail) tokens.push(['p', tail + '>']);
    else tokens.push(['p', '>']);
    return { tokens, end: i + m[0].length };
  }
  if ((m = rest.match(/^<[A-Za-z][A-Za-z0-9:-]*/))) {
    tokens.push(['p', '<']);
    tokens.push(['nt', m[0].slice(1)]);
    i += m[0].length;
    // attributes
    while (i < code.length) {
      const r = code.slice(i);
      let am;
      if ((am = r.match(/^\s+/))) { tokens.push(['', am[0]]); i += am[0].length; continue; }
      if (r.startsWith('/>')) { tokens.push(['p', '/>']); return { tokens, end: i + 2 }; }
      if (r[0] === '>') { tokens.push(['p', '>']); return { tokens, end: i + 1 }; }
      if ((am = r.match(/^[A-Za-z_:-][A-Za-z0-9:_.-]*/))) {
        tokens.push(['na', am[0]]); i += am[0].length; continue;
      }
      if (r[0] === '=') { tokens.push(['o', '=']); i++; continue; }
      if ((am = r.match(/^"[^"]*"/)) || (am = r.match(/^'[^']*'/))) {
        tokens.push(['s', am[0]]); i += am[0].length; continue;
      }
      if ((am = r.match(/^[^\s>]+/))) {
        tokens.push(['s', am[0]]); i += am[0].length; continue;
      }
      tokens.push(['', r[0]]); i++;
    }
    return { tokens, end: i };
  }
  // not a tag after all
  tokens.push(['', '<']);
  return { tokens, end: i + 1 };
}

export function tokenize(code) {
  const tokens = [];
  let i = 0;
  let m;
  while (i < code.length) {
    const rest = code.slice(i);
    if ((m = rest.match(/^<!--[\s\S]*?-->/))) {
      tokens.push(['cm', m[0]]); i += m[0].length; continue;
    }
    if ((m = rest.match(/^<!DOCTYPE[\s\S]*?>/i))) {
      tokens.push(['cp', m[0]]); i += m[0].length; continue;
    }
    if ((m = rest.match(/^<!\[CDATA\[[\s\S]*?\]\]>/i))) {
      tokens.push(['cp', m[0]]); i += m[0].length; continue;
    }
    if ((m = rest.match(/^&[A-Za-z][A-Za-z0-9]*;|^&#[0-9]+;|^&#[xX][0-9a-fA-F]+;/))) {
      tokens.push(['ni', m[0]]); i += m[0].length; continue;
    }
    // <script> ... </script>
    if ((m = rest.match(/^<script(?=[\s>])/i))) {
      const openEnd = code.indexOf('>', i);
      if (openEnd !== -1) {
        const tag = tokenizeTag(code, i);
        tokens.push(...tag.tokens);
        const closeMatch = /<\/script\s*>/i.exec(code.slice(tag.end));
        const contentEnd = closeMatch ? tag.end + closeMatch.index : code.length;
        const jsCode = code.slice(tag.end, contentEnd);
        if (jsCode) tokens.push(...tokenizeJs(jsCode));
        i = contentEnd;
        if (closeMatch) {
          const closeToks = tokenizeTag(code, i);
          tokens.push(...closeToks.tokens);
          i = closeToks.end;
        }
        continue;
      }
    }
    if (rest[0] === '<' && /^<\/?[A-Za-z]/.test(rest)) {
      const tag = tokenizeTag(code, i);
      tokens.push(...tag.tokens);
      i = tag.end;
      continue;
    }
    if ((m = rest.match(/^[^<&]+/))) {
      tokens.push(['', m[0]]); i += m[0].length; continue;
    }
    tokens.push(['', rest[0]]);
    i++;
  }
  return tokens;
}

// Extension support: fenced_code, codehilite, tables, toc.

import { highlight } from './pygments/formatter.mjs';
import { tokenize as pyTokenize } from './pygments/python.mjs';
import { tokenize as jsTokenize } from './pygments/javascript.mjs';
import { tokenize as bashTokenize } from './pygments/bash.mjs';
import { tokenize as htmlTokenize } from './pygments/html.mjs';
import { tokenize as textTokenize } from './pygments/text.mjs';

const LEXERS = {
  python: pyTokenize, py: pyTokenize, python3: pyTokenize, py3: pyTokenize,
  javascript: jsTokenize, js: jsTokenize, jsx: jsTokenize, node: jsTokenize,
  bash: bashTokenize, sh: bashTokenize, shell: bashTokenize,
  zsh: bashTokenize, ksh: bashTokenize, console: bashTokenize,
  html: htmlTokenize, xhtml: htmlTokenize, xml: htmlTokenize,
  text: textTokenize, plain: textTokenize, plaintext: textTokenize,
};

function getLexer(lang) {
  if (!lang) return textTokenize;
  return LEXERS[lang.toLowerCase()] || textTokenize;
}

// Python-Markdown codehilite: CodeHilite.hilite()
// src is stripped of leading/trailing newlines, highlighted with
// HtmlFormatter(nowrap=True) and wrapped manually.
export function codehilite(src, lang) {
  const stripped = src.replace(/^[\n]+/, '').replace(/[\n]+$/, '');
  const body = highlight(stripped, getLexer(lang));
  return `<div class="codehilite"><pre><span></span><code>${body}</code></pre></div>`;
}

// Markdown's own escaping for code blocks: &, <, > only.
export function escapeCode(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// fenced_code without codehilite: plain <pre><code> block.
export function fencedBlock(src, lang) {
  const cls = lang ? ` class="language-${lang}"` : '';
  return `<pre><code${cls}>${escapeCode(src)}\n</code></pre>`;
}

// ---- toc ----

export function slugify(value) {
  // unicodedata.normalize('NFKD') + encode('ascii', 'ignore')
  let v = value.normalize('NFKD').replace(/[^\x00-\x7F]/g, '');
  v = v.replace(/[^\w\s-]/g, '').trim().toLowerCase();
  v = v.replace(/[-\s]+/g, '-');
  return v;
}

export class TocTracker {
  constructor() {
    this.used = new Set();
  }

  unique(slug) {
    let candidate = slug;
    let i = 1;
    while (this.used.has(candidate)) {
      candidate = `${slug}_${i}`;
      i++;
    }
    this.used.add(candidate);
    return candidate;
  }
}

// ---- tables ----

// Does `line` look like a table separator row?  e.g. | --- | :-: | --: |
export function isTableSeparator(line) {
  if (!line.includes('|')) return false;
  const cells = splitRow(line);
  if (cells.length === 0) return false;
  return cells.every((c) => /^:?-+:?$/.test(c.trim()) && c.trim() !== '');
}

export function splitRow(line) {
  let row = line.trim();
  if (row.startsWith('|')) row = row.slice(1);
  if (row.endsWith('|')) row = row.slice(0, -1);
  return row.split('|');
}

export function parseAlignment(sepLine) {
  return splitRow(sepLine).map((cell) => {
    const c = cell.trim();
    const left = c.startsWith(':');
    const right = c.endsWith(':');
    if (left && right) return 'center';
    if (left) return 'left';
    if (right) return 'right';
    return null;
  });
}

// Inline processing: code spans, backslash escapes, links, images,
// autolinks, inline raw HTML, emphasis, hard breaks and entity-aware
// escaping. Mirrors the observable behavior of Python-Markdown's
// inline patterns.

import { HtmlStash } from './htmlStash.mjs';

// Escape &, <, > in text, preserving existing entities.
export function escapeText(text) {
  return text
    .replace(/&(?!(?:[a-zA-Z][a-zA-Z0-9]*|#[0-9]+|#[xX][0-9a-fA-F]+);)/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeAttrib(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function stripTags(html) {
  return html.replace(/<[^>]*>/g, '');
}

function unescapeEntities(text) {
  return text
    .replace(/&#x([0-9a-fA-F]+);/g, (m, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#([0-9]+);/g, (m, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&(amp|lt|gt|quot|apos|nbsp);/g, (m, name) => ({
      amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
    })[name]);
}

// Plain-text rendering of processed inline html (used for heading slugs).
export function plainText(html) {
  return unescapeEntities(stripTags(html));
}

function obfuscate(text) {
  let out = '';
  for (const ch of text) out += `&#${ch.codePointAt(0)};`;
  return out;
}

const BACKSLASH_ESCAPABLE = '\\`*_{}[]()#+-.!';
const CODE_SPAN_RE = /(?<!`)(`+)(?!`)([\s\S]+?)(?<!`)\1(?!`)/g;
const AUTOLINK_RE = /<((?:https?|ftp):[^<>\s]*)>/g;
const EMAIL_RE = /<([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})>/g;
const INLINE_HTML_RE = /<!--[\s\S]*?-->|<\/?[A-Za-z][A-Za-z0-9:-]*(?:\s+[A-Za-z_:][A-Za-z0-9:_.-]*(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s"'=<>`]+))?)*\s*\/?>/g;
const LINK_RE = /(!?)\[((?:[^\]\\]|\\[\s\S])*)\]\(\s*(?:<([^>\n]*)>|([^\s()]*))(?:\s+(?:"([^"\n]*)"|'([^'\n]*)'|\(([^)\n]*)\)))?\s*\)/g;

export function inline(text) {
  const stash = new HtmlStash('klzzwxh:');
  let t = text;

  // 1. code spans
  t = t.replace(CODE_SPAN_RE, (m, ticks, content) => {
    let c = content.trim();
    const html = `<code>${escapeText(c)}</code>`;
    return stash.store(html);
  });

  // 2. backslash escapes
  t = t.replace(/\\([\\`*_{}\[\]()#+\-.!>])/g, (m, ch) => stash.store(escapeText(ch)));

  // 3. autolinks
  t = t.replace(AUTOLINK_RE, (m, url) =>
    stash.store(`<a href="${escapeAttrib(url)}">${escapeText(url)}</a>`));
  t = t.replace(EMAIL_RE, (m, addr) =>
    stash.store(`<a href="${obfuscate('mailto:' + addr)}">${obfuscate(addr)}</a>`));

  // 4. inline raw html
  t = t.replace(INLINE_HTML_RE, (m) => stash.store(m));

  // 5. links and images (link text is processed recursively)
  t = t.replace(LINK_RE, (m, bang, label, urlAngle, urlPlain, t1, t2, t3) => {
    const url = urlAngle !== undefined ? urlAngle : (urlPlain || '');
    const title = t1 !== undefined ? t1 : (t2 !== undefined ? t2 : t3);
    if (bang) {
      const alt = escapeAttrib(plainText(inline(label)));
      let html = `<img alt="${alt}" src="${escapeAttrib(url)}"`;
      if (title !== undefined) html += ` title="${escapeAttrib(title)}"`;
      html += ' />';
      return stash.store(html);
    }
    const inner = inline(label);
    let html = `<a href="${escapeAttrib(url)}"`;
    if (title !== undefined) html += ` title="${escapeAttrib(title)}"`;
    html += `>${inner}</a>`;
    return stash.store(html);
  });

  // 6. escape remaining text
  t = escapeText(t);

  // 7. emphasis
  t = t.replace(/\*\*\*([\s\S]+?)\*\*\*/g, '<strong><em>$1</em></strong>');
  t = t.replace(/\*\*([\s\S]+?)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/\*([\s\S]+?)\*/g, '<em>$1</em>');
  t = t.replace(/(?<![\p{L}\p{N}_])___([\s\S]+?)___(?![\p{L}\p{N}_])/gu, '<strong><em>$1</em></strong>');
  t = t.replace(/(?<![\p{L}\p{N}_])__([\s\S]+?)__(?![\p{L}\p{N}_])/gu, '<strong>$1</strong>');
  t = t.replace(/(?<![\p{L}\p{N}_])_([\s\S]+?)_(?![\p{L}\p{N}_])/gu, '<em>$1</em>');

  // 8. hard breaks
  t = t.replace(/ {2,}\n/g, '<br />\n');
  t = t.replace(/\\\n/g, '<br />\n');

  // 9. restore stashed fragments
  t = stash.restore(t);
  return t;
}

// Block-level parsing and serialization, plus raw HTML block extraction,
// mirroring the observable behavior of Python-Markdown.

import { HtmlStash, STX, ETX, BLOCK_PLACEHOLDER_PREFIX } from './htmlStash.mjs';
import { inline, plainText, escapeText } from './inline.mjs';
import {
  codehilite, fencedBlock, escapeCode,
  isTableSeparator, splitRow, parseAlignment,
  slugify, TocTracker,
} from './extensions.mjs';

const BLOCK_TAGS = new Set([
  'address', 'article', 'aside', 'base', 'basefont', 'blockquote', 'body',
  'caption', 'center', 'col', 'colgroup', 'dd', 'details', 'dialog', 'dir',
  'div', 'dl', 'dt', 'fieldset', 'figcaption', 'figure', 'footer', 'form',
  'frame', 'frameset', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'head', 'header',
  'hr', 'html', 'iframe', 'legend', 'li', 'link', 'main', 'menu', 'menuitem',
  'nav', 'noframes', 'ol', 'optgroup', 'option', 'p', 'param', 'search',
  'section', 'summary', 'table', 'tbody', 'td', 'tfoot', 'th', 'thead',
  'title', 'tr', 'track', 'ul', 'script', 'style', 'pre', 'textarea',
]);

function isBlank(line) {
  return /^[ \t]*$/.test(line);
}

function indentOf(line) {
  let n = 0;
  for (const ch of line) {
    if (ch === ' ') n++;
    else if (ch === '\t') n += 4 - (n % 4);
    else break;
  }
  return n;
}

// ---------------------------------------------------------------------------
// Raw HTML block extraction (HTMLExtractor equivalent).
// Works on the raw text; returns placeholder-substituted lines.
// ---------------------------------------------------------------------------
export function extractHtmlBlocks(text, stash) {
  const lines = text.split('\n');
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    let m;
    let end = -1; // last line index of the block (inclusive)

    if ((m = line.match(/^ {0,3}<!--/))) {
      // html comment: until line containing -->
      end = i;
      while (end < lines.length && !lines[end].includes('-->')) end++;
      if (end >= lines.length) end = lines.length - 1;
    } else if (/^ {0,3}<\?/.test(line)) {
      end = i;
      while (end < lines.length && !lines[end].includes('?>')) end++;
      if (end >= lines.length) end = lines.length - 1;
    } else if (/^ {0,3}<![A-Z]/.test(line)) {
      end = i;
      while (end < lines.length && !lines[end].includes('>')) end++;
      if (end >= lines.length) end = lines.length - 1;
    } else if (/^ {0,3}<!\[CDATA\[/.test(line)) {
      end = i;
      while (end < lines.length && !lines[end].includes(']]>')) end++;
      if (end >= lines.length) end = lines.length - 1;
    } else if (/^ {0,3}<\/[A-Za-z]/.test(line)) {
      // closing tag at line start: until blank line
      end = i;
      while (end + 1 < lines.length && !isBlank(lines[end + 1])) end++;
    } else if ((m = line.match(/^ {0,3}<([A-Za-z][A-Za-z0-9]*)(?=[\s/>]|$)/)) &&
               BLOCK_TAGS.has(m[1].toLowerCase())) {
      const tag = m[1].toLowerCase();
      // scan for the matching closing tag from here on (may cross blanks)
      const closeRe = new RegExp(`</${tag}\\s*>`, 'i');
      end = -1;
      for (let j = i; j < lines.length; j++) {
        const searchFrom = j === i ? m[0].length : 0;
        if (closeRe.test(lines[j].slice(searchFrom))) { end = j; break; }
      }
      if (end === -1) {
        // no closing tag: until blank line
        end = i;
        while (end + 1 < lines.length && !isBlank(lines[end + 1])) end++;
      }
    }

    if (end >= i && end !== -1) {
      // block found: lines[i..end]; consume following blank lines
      let k = end + 1;
      while (k < lines.length && isBlank(lines[k])) k++;
      const hadTrailingBlank = k > end + 1;
      const blockLines = lines.slice(i, end + 1);
      blockLines[blockLines.length - 1] = blockLines[blockLines.length - 1].replace(/[ \t]+$/, '');
      let content = blockLines.join('\n');
      if (hadTrailingBlank) content += '\n';
      out.push(stash.store(content));
      i = k;
    } else {
      out.push(line);
      i++;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Block parser
// ---------------------------------------------------------------------------

const PLACEHOLDER_LINE_RE = new RegExp(`^ {0,3}${STX}${BLOCK_PLACEHOLDER_PREFIX}(\\d+)${ETX}[ \\t]*$`);
const FENCE_RE = /^ {0,3}(`{3,}|~{3,})[ \t]*(.*?)[ \t]*$/;
const ATX_RE = /^ {0,3}(#{1,6})(.*)$/;
const HR_RE = /^ {0,3}((\*[ \t]*){3,}|(_[ \t]*){3,}|(-[ \t]*){3,})$/;
const SETEXT_RE = /^ {0,3}(=+|-+)[ \t]*$/;
const LIST_RE = /^( {0,3})([*+-]|\d{1,9}[.)])([ \t]+)(.*)$/;
const QUOTE_RE = /^ {0,3}>[ \t]?/;
const INDENTED_RE = /^(?: {4}|\t)/;

export class BlockParser {
  constructor(exts, stash) {
    this.exts = exts;
    this.stash = stash;
    this.toc = new TocTracker();
  }

  parse(lines) {
    const nodes = [];
    let i = 0;
    while (i < lines.length) {
      const line = lines[i];
      if (isBlank(line)) { i++; continue; }
      let m;

      // raw html placeholder
      if ((m = line.match(PLACEHOLDER_LINE_RE))) {
        nodes.push({ type: 'raw', html: this.stash.get(Number(m[1])) });
        i++;
        continue;
      }

      // fenced code
      if (this.exts.fenced && (m = line.match(FENCE_RE))) {
        const fence = m[1];
        const fenceChar = fence[0];
        let lang = m[2].split(/[ \t]/)[0] || '';
        if (lang.startsWith('.')) lang = lang.slice(1);
        let j = i + 1;
        const closeRe = new RegExp(`^ {0,3}${fenceChar === '`' ? '`' : '~'}{${fence.length},}[ \\t]*$`);
        while (j < lines.length && !closeRe.test(lines[j])) j++;
        const code = lines.slice(i + 1, Math.min(j, lines.length)).join('\n');
        const afterFence = j < lines.length ? j + 1 : j;
        if (this.exts.codehilite) {
          // raw html block: consume following blank lines
          let k = afterFence;
          while (k < lines.length && isBlank(lines[k])) k++;
          let html = codehilite(code, lang);
          if (k > afterFence) html += '\n';
          nodes.push({ type: 'raw', html });
          i = k;
        } else {
          nodes.push({ type: 'fence', code, lang });
          i = afterFence;
        }
        continue;
      }

      // atx heading
      if ((m = line.match(ATX_RE))) {
        let content = m[2].replace(/#+[ \t]*$/, '').trim();
        nodes.push({ type: 'h', level: m[1].length, text: content });
        i++;
        continue;
      }

      // horizontal rule
      if (HR_RE.test(line)) {
        nodes.push({ type: 'hr' });
        i++;
        continue;
      }

      // setext heading
      if (i + 1 < lines.length && SETEXT_RE.test(lines[i + 1]) && !isBlank(line)) {
        const level = lines[i + 1].trim()[0] === '=' ? 1 : 2;
        nodes.push({ type: 'h', level, text: line.trim() });
        i += 2;
        continue;
      }

      // table
      if (this.exts.tables && i + 1 < lines.length &&
          isTableSeparator(lines[i + 1]) && line.includes('|')) {
        i = this.parseTable(lines, i, nodes);
        continue;
      }

      // list
      if (LIST_RE.test(line)) {
        i = this.parseList(lines, i, nodes);
        continue;
      }

      // blockquote
      if (QUOTE_RE.test(line)) {
        i = this.parseQuote(lines, i, nodes);
        continue;
      }

      // indented code block
      if (INDENTED_RE.test(line)) {
        const codeLines = [];
        let j = i;
        let pending = [];
        while (j < lines.length) {
          if (INDENTED_RE.test(lines[j])) {
            codeLines.push(...pending, lines[j].replace(/^(?: {4}|\t)/, ''));
            pending = [];
            j++;
          } else if (isBlank(lines[j])) {
            pending.push('');
            j++;
          } else {
            break;
          }
        }
        nodes.push({ type: 'code', text: codeLines.join('\n') });
        i = j;
        continue;
      }

      // paragraph
      const paraLines = [line];
      let j = i + 1;
      while (j < lines.length && !isBlank(lines[j])) {
        const l = lines[j];
        if (PLACEHOLDER_LINE_RE.test(l) || ATX_RE.test(l) || HR_RE.test(l) ||
            QUOTE_RE.test(l) || (this.exts.fenced && FENCE_RE.test(l)) ||
            LIST_RE.test(l) || SETEXT_RE.test(l)) break;
        // setext continuation of the paragraph
        paraLines.push(l);
        j++;
      }
      // a setext underline turns the whole paragraph into a heading
      nodes.push({ type: 'p', text: paraLines.join('\n') });
      i = j;
    }
    return nodes;
  }

  parseTable(lines, i, nodes) {
    const header = splitRow(lines[i]).map((c) => c.trim());
    const aligns = parseAlignment(lines[i + 1]);
    const cols = header.length;
    const rows = [];
    let j = i + 2;
    while (j < lines.length && !isBlank(lines[j]) && lines[j].includes('|')) {
      const cells = splitRow(lines[j]).map((c) => c.trim());
      while (cells.length < cols) cells.push('');
      rows.push(cells.slice(0, cols));
      j++;
    }
    nodes.push({ type: 'table', header, aligns, rows });
    return j;
  }

  parseList(lines, i, nodes) {
    const first = lines[i].match(LIST_RE);
    const ordered = /\d/.test(first[2][0]);
    const baseIndent = first[1].length;
    const contentIndent = baseIndent + first[2].length + first[3].length;
    const items = [];
    let loose = false;
    let j = i;

    const itemRe = new RegExp(`^ {${baseIndent}}(${ordered ? '\\d{1,9}[.)]' : '[*+-]'})([ \\t]+)(.*)$`);

    while (j < lines.length) {
      const m = lines[j].match(itemRe);
      if (!m) break;
      const content = [m[3]];
      j++;
      // continuation lines of this item
      while (j < lines.length) {
        const l = lines[j];
        if (isBlank(l)) {
          // look ahead over blanks
          let k = j;
          while (k < lines.length && isBlank(lines[k])) k++;
          if (k < lines.length && (itemRe.test(lines[k]) || indentOf(lines[k]) >= contentIndent)) {
            loose = true;
            content.push('');
            j = j + 1; // keep one blank marker; skip the rest next round
            j = k;
            continue;
          }
          break;
        }
        if (itemRe.test(l)) break;
        if (indentOf(l) >= contentIndent) {
          content.push(l.slice(contentIndent));
          j++;
          continue;
        }
        break;
      }
      items.push(content);
    }

    const itemNodes = items.map((content) => {
      // drop trailing blank markers
      while (content.length && content[content.length - 1] === '') content.pop();
      return this.parse(content);
    });
    nodes.push({ type: ordered ? 'ol' : 'ul', items: itemNodes, loose });
    return j;
  }

  parseQuote(lines, i, nodes) {
    const quoteLines = [];
    let j = i;
    while (j < lines.length) {
      const l = lines[j];
      if (QUOTE_RE.test(l)) {
        quoteLines.push(l.replace(QUOTE_RE, ''));
        j++;
      } else if (!isBlank(l) && !ATX_RE.test(l) && !HR_RE.test(l) &&
                 !LIST_RE.test(l) && !PLACEHOLDER_LINE_RE.test(l) &&
                 !(this.exts.fenced && FENCE_RE.test(l))) {
        // lazy continuation
        quoteLines.push(l);
        j++;
      } else {
        break;
      }
    }
    const inner = this.parse(quoteLines);
    nodes.push({ type: 'blockquote', children: inner });
    return j;
  }

  // ---- serialization ----

  headingAttrs(node) {
    if (!this.exts.toc) return '';
    const slug = this.toc.unique(slugify(plainText(inline(node.text))));
    return ` id="${slug}"`;
  }

  serialize(nodes) {
    return nodes.map((n) => this.serializeNode(n)).join('\n');
  }

  serializeNode(node) {
    switch (node.type) {
      case 'raw':
        return node.html;
      case 'p':
        return `<p>${inline(node.text)}</p>`;
      case 'h':
        return `<h${node.level}${this.headingAttrs(node)}>${inline(node.text)}</h${node.level}>`;
      case 'hr':
        return '<hr />';
      case 'code':
        return `<pre><code>${escapeCode(node.text)}\n</code></pre>`;
      case 'fence': {
        const cls = node.lang ? ` class="language-${node.lang}"` : '';
        return `<pre><code${cls}>${escapeCode(node.code)}\n</code></pre>`;
      }
      case 'blockquote':
        return `<blockquote>\n${this.serialize(node.children)}\n</blockquote>`;
      case 'ul':
      case 'ol': {
        const tag = node.type;
        const items = node.items.map((children) => {
          if (!node.loose && children.length === 1 && children[0].type === 'p') {
            return `<li>${inline(children[0].text)}</li>`;
          }
          if (!node.loose && children.length > 0 && children[0].type === 'p') {
            const [first, ...rest] = children;
            return `<li>${inline(first.text)}${rest.map((c) => this.serializeNode(c)).join('')}\n</li>`;
          }
          return `<li>\n${this.serialize(children)}\n</li>`;
        });
        return `<${tag}>\n${items.join('\n')}\n</${tag}>`;
      }
      case 'table': {
        const attr = (a) => (a ? ` style="text-align: ${a};"` : '');
        const th = node.header.map((c, idx) =>
          `<th${attr(node.aligns[idx])}>${inline(c)}</th>`).join('\n');
        const trs = node.rows.map((row) =>
          `<tr>\n${row.map((c, idx) => `<td${attr(node.aligns[idx])}>${inline(c)}</td>`).join('\n')}\n</tr>`);
        let out = `<table>\n<thead>\n<tr>\n${th}\n</tr>\n</thead>`;
        if (trs.length) {
          out += `\n<tbody>\n${trs.join('\n')}\n</tbody>\n</table>`;
        } else {
          out += `\n</table>`;
        }
        return out;
      }
      default:
        return '';
    }
  }
}

export function markdown(text, extensions = []) {
  const exts = {
    fenced: extensions.includes('fenced_code') || extensions.includes('extra'),
    tables: extensions.includes('tables') || extensions.includes('extra'),
    codehilite: extensions.includes('codehilite'),
    toc: extensions.includes('toc'),
  };
  const cleaned = text.replace(/\r\n?/g, '\n');
  const stash = new HtmlStash();
  const lines = extractHtmlBlocks(cleaned, stash);
  const parser = new BlockParser(exts, stash);
  const nodes = parser.parse(lines);
  let out = parser.serialize(nodes);
  out = stash.restore(out);
  return out.replace(/^\n+/, '').replace(/\n+$/, '');
}

