// Node.js (ESM) port of test19.py — Markdown processing with transformation
// chain. Usage: node test19.mjs --a A --b B --c C --d D --e E --f F

import { basename } from 'node:path';
import { markdown } from './lib/blocks.mjs';

const PROG = basename(process.argv[1] || 'test19.mjs');
const OPTION_NAMES = ['a', 'b', 'c', 'd', 'e', 'f'];

function usage() {
  return `usage: ${PROG} [-h] ${OPTION_NAMES.map((n) => `--${n} ${n.toUpperCase()}`).join(' ')}`;
}

function errorExit(message) {
  process.stderr.write(`${usage()}\n${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  let out = `${usage()}\n\nMarkdown processing with transformation chain\n\noptions:\n`;
  out += '  -h, --help  show this help message and exit\n';
  for (const n of OPTION_NAMES) out += `  --${n} ${n.toUpperCase()}\n`;
  process.stdout.write(out);
  process.exit(0);
}

// Minimal argparse equivalent: required options --a .. --f, each taking
// exactly one argument; supports "--opt value" and "--opt=value".
function parseArgs(argv) {
  const values = {};
  const extras = [];
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      printHelp();
    } else if (arg.startsWith('--')) {
      let name = arg.slice(2);
      let value = null;
      const eq = name.indexOf('=');
      if (eq !== -1) {
        value = name.slice(eq + 1);
        name = name.slice(0, eq);
      }
      if (!OPTION_NAMES.includes(name)) {
        extras.push(arg);
        i++;
        continue;
      }
      if (value === null) {
        if (i + 1 >= argv.length) {
          errorExit(`argument --${name}: expected one argument`);
        }
        const next = argv[i + 1];
        // argparse: a following option-like token is not consumed as a value,
        // unless it looks like a negative number.
        if (next.startsWith('-') && next !== '-' && !/^-\d+$|^-\d*\.\d+$/.test(next)) {
          errorExit(`argument --${name}: expected one argument`);
        }
        value = next;
        i += 2;
      } else {
        i++;
      }
      values[name] = value;
    } else {
      extras.push(arg);
      i++;
    }
  }
  const missing = OPTION_NAMES.filter((n) => !(n in values));
  if (missing.length) {
    errorExit(`the following arguments are required: ${missing.map((n) => `--${n}`).join(', ')}`);
  }
  if (extras.length) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  // Phase 1: Basic conversions
  const phase1_a = markdown(args.a);
  const phase1_b = markdown(args.b);
  const phase1_c = markdown(args.c);

  // Phase 2: With extensions
  const phase2_d = markdown(args.d, ['extra', 'tables']);
  const phase2_e = markdown(args.e, ['codehilite', 'fenced_code']);
  const phase2_f = markdown(args.f, ['toc']);

  // Phase 3: Combined processing
  const phase3_combined = markdown(`
# Combined Document

## Section A
${phase1_a}

## Section B
${phase1_b}

## Section C
${phase1_c}

## Section D
${phase2_d}

## Section E
${phase2_e}

## Section F
${phase2_f}
`);

  // Phase 4: Nested transformations
  const phase4_nested = markdown(`<article>${phase3_combined}</article>`);

  // Phase 5: Final processing with all features
  const phase5_final = markdown(
    [args.a, args.b, args.c, args.d, args.e, args.f].join('\n\n'),
    ['extra', 'tables', 'codehilite', 'fenced_code', 'toc']
  );

  console.log(phase1_a);
  console.log(phase1_b);
  console.log(phase1_c);
  console.log(phase2_d);
  console.log(phase2_e);
  console.log(phase2_f);
  console.log(phase3_combined);
  console.log(phase4_nested);
  console.log(phase5_final);
}

main();

